={{ (() => {
  // Téléphone du patient courant, normalisé (chiffres uniquement)
  const telCourant = String(
    $('02 — Extraire données message').first().json.telephone || ''
  ).replace(/\D/g, '');

  // On cherche une ligne dont le téléphone correspond EXACTEMENT
  // String() obligatoire : telephone est numérique dans la Sheet
  const ligne = $('11-PRD — Chercher patient existant').all().find(i => {
    const telLigne = String(i.json.telephone || '').replace(/\D/g, '');
    const aPrenom  = String(i.json.prenom || '').trim() !== '';
    return telLigne === telCourant && aPrenom;   // match strict téléphone + prénom présent
  });

  return ligne ? String(ligne.json.prenom).trim() : '';
})() }}

