parameters.jsCode:
const items = $input.all();
const safe = (fn, fallback = '') => {
  try { const v = fn(); return v ?? fallback; } catch (e) { return fallback; }
};
let ctx = {};
try {
  ctx = JSON.parse($('05 — Lire session patient').first().json.contexte || '{}');
} catch (e) { ctx = {}; }

const edit = safe(() => $('Edit Fields').first().json, {});
const telephone = String(
  edit.telephone ||
  safe(() => $('02 — Extraire données message').first().json.telephone, '') ||
  safe(() => $('05 — Lire session patient').first().json.telephone, '') ||
  ''
).replace(/\D/g, '');

const prenomDepuisSheet = (() => {
  try {
    const lignes = $('11-PRD — Chercher patient existant').all();
    const ligneAvecPrenom = lignes.find(l => l.json && String(l.json.prenom || '').trim() !== '');
    return ligneAvecPrenom ? String(ligneAvecPrenom.json.prenom).trim() : '';
  } catch (e) { return ''; }
})();

const prenom = String(edit.prenom || prenomDepuisSheet || ctx.prenom || '').trim();

const mode_ecriture_final =
  edit.mode_ecriture_final ||
  ctx.mode_ecriture_final ||
  safe(() => $('SET — Profil linguistique final').first().json.mode_ecriture_final, '') ||
  safe(() => $('09 — Parser réponse IA').first().json.mode_ecriture, '') ||
  'inconnu';

/* ✅ CORRIGÉ — On lit start ET end → intervalles occupés en ms UTC (temps absolu) */
const intervallesOccupes = items
  .map(i => {
    const s = i.json && i.json.start ? (i.json.start.dateTime || i.json.start.date) : null;
    const e = i.json && i.json.end   ? (i.json.end.dateTime   || i.json.end.date)   : null;
    if (!s) return null;
    const startMs = new Date(s).getTime();
    const endMs = e ? new Date(e).getTime() : startMs + 30 * 60000; /* fallback 30 min */
    if (isNaN(startMs) || isNaN(endMs)) return null;
    return { startMs, endMs };
  })
  .filter(Boolean);

const horairesTravail = [
  '09:00','09:30','10:00','10:30','11:00','11:30',
  '14:00','14:30','15:00','15:30','16:00','16:30'
];
const joursOuvres = [1, 2, 3, 4, 5];      /* lun→ven (getUTCDay) */
const DUREE_CRENEAU_MIN = 30;
const TZ = 'Africa/Casablanca';

// ── Formatage de date patient localisé (déterministe, indépendant du fuseau serveur) ──
// Tables maghrébines : chiffres occidentaux + noms de mois marocains (يوليوز, غشت, دجنبر…).
// On n'utilise PAS Intl('ar') car il renvoie chiffres arabes-indiens et mois orientaux (يوليو).
const JOURS_AR = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
const MOIS_AR  = ['يناير','فبراير','مارس','أبريل','ماي','يونيو','يوليوز','غشت','شتنبر','أكتوبر','نونبر','دجنبر'];
function formaterDatePatient(instant, heure, mode) {
  const arabe = (mode === 'arabe_fussha' || mode === 'darija_arabe'); // rendu RTL/arabe
  if (arabe) {
    // Composantes extraites AU FUSEAU MAROC (getMonth/getDay serveur = non fiable)
    const ymd = instant.toLocaleDateString('en-CA', { timeZone: TZ }); // "2026-07-29"
    const [, M, D] = ymd.split('-').map(Number);
    const dow = new Date(`${ymd}T12:00:00+01:00`).getUTCDay(); // 0=dim..6=sam, fiable
    return `${JOURS_AR[dow]} ${D} ${MOIS_AR[M - 1]} على الساعة ${heure}`;
  }
  let aff = instant.toLocaleDateString('fr-FR', {
    timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
  });
  aff = aff.charAt(0).toUpperCase() + aff.slice(1);
  return `${aff} à ${heure.replace(':', 'h')}`;
}

// ── Fenêtre de recherche des créneaux à proposer au patient. ──────────
// Si AUCUN créneau libre dans cette fenêtre → le patient bascule en
// liste d'attente (branche LA-IN). 14 = quinzaine. Élargir ce nombre
// réduit les inscriptions en liste d'attente ; le réduire les augmente.
const FENETRE_RECHERCHE_JOURS = 14;
const maintenant = new Date();
const creneauxLibres = [];

/* date locale Maroc "YYYY-MM-DD" pour aujourd'hui + k jours */
const ymdMaroc = (k) =>
  new Date(maintenant.getTime() + k * 86400000)
    .toLocaleDateString('en-CA', { timeZone: TZ });

for (let k = 0; k <= FENETRE_RECHERCHE_JOURS && creneauxLibres.length < 3; k++) {
  const ymd = ymdMaroc(k);
  /* midi Maroc = 11:00Z, même date → getUTCDay() donne le bon jour de semaine */
  const jourSemaine = new Date(`${ymd}T12:00:00+01:00`).getUTCDay();
  if (!joursOuvres.includes(jourSemaine)) continue;

  for (const heure of horairesTravail) {
    if (creneauxLibres.length >= 3) break;

    /* ✅ instant ABSOLU exact du créneau, offset Maroc explicite */
    const instant = new Date(`${ymd}T${heure}:00+01:00`);
    // CAS 3 — délai minimal de réservation : 30 min de tampon.
    // Un créneau à moins de 30 min est impraticable → on l'exclut.
    const DELAI_MIN_MS = 30 * 60 * 1000; // 30 minutes
    if (instant.getTime() <= maintenant.getTime() + DELAI_MIN_MS) continue;

    const creneauStart = instant.getTime();
    const creneauEnd = creneauStart + DUREE_CRENEAU_MIN * 60000;

    /* chevauchement en temps absolu */
    const occupe = intervallesOccupes.some(ev =>
      creneauStart < ev.endMs && creneauEnd > ev.startMs
    );
    if (occupe) continue;

    // Format complet patient, localisé selon le mode (FR ou AR fussha).
    // La date affichée doit être TOTALEMENT en fussha quand mode_ecriture_final = arabe_fussha.
    const affichage = formaterDatePatient(instant, heure, mode_ecriture_final);

    creneauxLibres.push({
      index: String(creneauxLibres.length + 1),
      date_iso: ymd,
      heure,
      affichage   // ex FR: "Mercredi 29 juillet 2026 à 10h00" | AR: "الأربعاء 29 يوليوز على الساعة 10:00"
    });
  }
}

return [{ json: { telephone, prenom, mode_ecriture_final, creneaux: creneauxLibres } }];

