={{ (() => {
  const mode = String($json.mode_ecriture_final || 'inconnu').trim().toLowerCase();

  const prenom = String($json.prenom || '').trim();
  const creneaux = Array.isArray($json.creneaux) ? $json.creneaux : [];

  const listeCreneaux = creneaux
    .map(c => `${c.index}️⃣ ${c.affichage}`)
