      listeCreneaux +
      '\n\nRépondez simplement avec le numéro du créneau qui vous convient.'
    );
  }

  if (mode === 'darija_latin') {
    return (
      (prenom ? `Mrhba ${prenom} 😊` : 'Mrhba bik 😊') +
      '\nHadi les créneaux disponibles 📅 :\n\n' +
      listeCreneaux +
      '\n\nKteb raqm l-créneau li nassebk.'
    );
  }

  if (mode === 'darija_arabe') {
    return (
      (prenom ? `مرحبا ${prenom} 😊` : 'مرحبا بك 😊') +
      '\nهادو هما المواعيد المتوفرة 📅 :\n\n' +
      listeCreneaux +
      '\n\nكتب رقم الموعد اللي مناسبك.'
    );
  }

if (mode === 'arabe_fussha') {
