      listeCreneaux +
      '\n\nأكتب رقم الموعد الذي يناسبك.'
    );
  }

  if (mode === 'mixte') {
    return (
      (prenom ? `Bonjour ${prenom} 😊` : 'Bonjour 😊') +
      '\nHadi les créneaux disponibles 📅 :\n\n' +
      listeCreneaux +
      '\n\nChoisis le numéro li nassebk.'
    );
