// Lit le choix du patient parmi les créneaux proposés
// prenom et mode_ecriture_final sont propagés depuis le contexte session
// (qui a été correctement alimenté par 15-PRD avant la proposition des créneaux)

const msg = $('02 — Extraire données message').first().json.message_brut.trim();
const tel = $('02 — Extraire données message').first().json.telephone;

let ctx;
try { ctx = JSON.parse($('05 — Lire session patient').first().json.contexte || '{}'); }
catch(e) { ctx = { creneaux: [] }; }

const mode = ctx.mode_ecriture_final || 'inconnu';
const prenom = ctx.prenom || '';

const choix = ctx.creneaux?.find(c => c.index === msg);

if (!choix) {
  return [{ json: {
    valide: false,
    telephone: tel,
    prenom: prenom,
    creneaux: ctx.creneaux || [],
    mode_ecriture_final: mode
  }}];
}

return [{ json: {
  valide: true,
  telephone: tel,
  prenom: prenom,
  creneau_choisi: choix,
  mode_ecriture_final: mode
}}];

parameters.textBody:
={{ (() => {
  // Dénominateur commun aux deux branches (Prise de RDV ET Report) :
  // le mode est lu depuis le contexte de session, jamais depuis 7-ACR2
  // qui n'existe pas sur le chemin Prise de RDV.
  let mode = 'inconnu';
  try {
    const ctx = JSON.parse($('05 — Lire session patient').first().json.contexte || '{}');
    mode = ctx.mode_ecriture_final || 'inconnu';
  } catch (e) {
    mode = 'inconnu';
  }

  const messages = {
    darija_latin:          'Ma fhemtch 😅 Kteb ghi 1, 2 wla 3 👇',
    darija_arabe:          'ما فهمتكش 😅 كتب غير 1 أو 2 أو 3 👇',
    arabe_fussha:          'لم أفهم إجابتكم 😊 يُرجى الرد فقط بالرقم 1 أو 2 أو 3.',
    francais_approximatif: 'Pas compris 😅 Tapez juste 1, 2 ou 3 👇',
    francais_correct:      'Je n\'ai pas compris votre réponse 😊 Veuillez répondre uniquement par 1, 2 ou 3.',
    mixte:                 'Mafhmt-k-sh 😅 Réponds juste 1, 2 wla 3 👇',
    inconnu:               'Veuillez répondre 1, 2 ou 3.'
  };

  return messages[mode] || messages.inconnu;
})() }}

