={{ (() => {
  const [h, m] = $json.creneau_choisi.heure.split(':').map(Number);
  const totalMin = h * 60 + m + 30; // +30 min de consultation
  const hFin = String(Math.floor(totalMin / 60)).padStart(2, '0');
  const mFin = String(totalMin % 60).padStart(2, '0');
  return $json.creneau_choisi.date_iso + 'T' + hFin + ':' + mFin + ':00+01:00';
})() }}

parameters.textBody:
={{ (() => {
  const data = $('7-ACR — Valider choix créneau').first().json;
  const cfg  = $('00-CONFIG — Variables cabinet').first().json;
  const prenom = String(data.prenom || '').trim();
  const creneau = data.creneau_choisi || {};
  const affichage = creneau.affichage || '';

  const projeter = (x) => {
    const m = String(x || '').trim().toLowerCase();
    if (m === 'arabe_fussha' || m === 'darija_arabe') return 'ar';
    return 'fr';
  };
  const isAr = projeter(data.mode_ecriture_final || $json.mode_ecriture_final) === 'ar';

  let medecin = String((isAr ? cfg.PROD_NOM_MEDECIN_AR : cfg.PROD_NOM_MEDECIN_FR) || cfg.PROD_NOM_MEDECIN || '').trim();
  const contientArabe = /[\u0600-\u06FF]/.test(medecin);
  if (medecin && !contientArabe && !/^dr\.?\s/i.test(medecin)) medecin = `Dr ${medecin}`;

  if (isAr) {
    return '✅ تم تأكيد موعدكم.\n\n' + `📅 ${affichage}\n` + `🏥 ${medecin}\n\n` +
           'ستصلكم رسالة تذكير قبل الموعد.\n' + (prenom ? `إلى اللقاء ${prenom} 😊` : 'إلى اللقاء 😊');
  }
  return '✅ Votre rendez-vous est confirmé.\n\n' + `📅 ${affichage}\n` + `🏥 ${medecin}\n\n` +
         'Vous recevrez un rappel avant le rendez-vous.\n' + (prenom ? `À bientôt ${prenom} 😊` : 'À bientôt 😊');
})() }}

={{ (() => {
  const data = $('7-ACR — Valider choix créneau').first().json;
  const event = $('7-ACR-CAL — Créer RDV Google Calendar').first().json;

  const prenom = String(data.prenom || 'Non renseigné').trim();
  const telephone = String(data.telephone || '').trim();
  const creneau = data.creneau_choisi || {};
  const heure = creneau.heure || '';
  const eventId = event.id || 'Non disponible';

  // Helper format date unifié
  const fmtDate = (iso) => {
    if (!iso) return 'Non renseignée';
    try {
      const d = new Date(String(iso).slice(0,10) + 'T00:00:00');
      let j = d.toLocaleDateString('fr-FR', { weekday: 'long' });
      j = j.charAt(0).toUpperCase() + j.slice(1);
      const jj = String(d.getDate()).padStart(2,'0');
      const mm = String(d.getMonth()+1).padStart(2,'0');
      return `${j} ${jj}/${mm}/${d.getFullYear()}`;
    } catch(e) { return String(iso); }
  };

  let medecin = $('00-CONFIG — Variables cabinet').first().json.PROD_NOM_MEDECIN || '';
  if (medecin && !/^dr\.?\s/i.test(medecin)) medecin = `Dr ${medecin}`;

  return (
    '🟢 Nouveau RDV confirmé\n\n' +
    `👤 Patient : ${prenom}\n` +
    `📞 Téléphone : ${telephone}\n` +
    `📅 Date : ${fmtDate(creneau.date_iso)}\n` +
    `🕒 Heure : ${heure}\n` +
    `🏥 Médecin : ${medecin}\n\n` +
    `🆔 Event Calendar : ${eventId}`
  );
})() }}

={{ (() => {
  const safe = (fn, def) => { try { const v = fn(); return (v === undefined || v === null) ? def : v; } catch(e) { return def; } };

  // Mode linguistique : source canonique SET — Profil linguistique final, fallback contexte session, puis parser
  let ctx = {};
  try { ctx = JSON.parse($('05 — Lire session patient').first().json.contexte || '{}'); } catch(e) { ctx = {}; }
  const modeBrut =
    safe(() => $('SET — Profil linguistique final').first().json.mode_ecriture_final, '') ||
    ctx.mode_ecriture_final ||
    safe(() => $('09 — Parser réponse IA').first().json.mode_ecriture, '') ||
    'inconnu';

  // Projection vers les 2 modes de sortie
  const m = String(modeBrut).trim().toLowerCase();
  let mode;
  if (m === 'arabe_fussha' || m === 'darija_latin' || m === 'darija_arabe' || m === 'mixte') mode = 'arabe_fussha';
  else mode = 'francais_correct';

  if (mode === 'arabe_fussha') {
    return (
      'عذرا 😊 لم نجد أي موعد محجوز باسمك.' +
      '\n\nهل ترغب في حجز موعد جديد ؟ أكتب «نعم» وسنبحث لك عن موعد متاح 📅'
    );
  }

  // francais_correct + fallback
  return (
    'Bonjour 😊 Nous n\'avons trouvé aucun rendez-vous confirmé à votre nom.' +
    '\n\nSouhaitez-vous prendre un nouveau rendez-vous ? Écrivez « OUI » et nous chercherons un créneau disponible 📅'
  );
})() }}

={{ (() => {
