const msg = $('02 — Extraire données message').first().json.message_brut.trim().toLowerCase();
const tel = $('02 — Extraire données message').first().json.telephone;
let ctx;
try { ctx = JSON.parse($('05 — Lire session patient').first().json.contexte || '{}'); }
catch(e) { ctx = {}; }

// Lecture event_id depuis Sheets en fallback (ctx ne le contient pas toujours)
const sheetData = (() => {
  try { return $('ANNUL — Chercher RDV existant').first().json; } catch(e) { return {}; }
})();

// Détection stricte des 3 intentions possibles
const confirme = /iyeh|oui|yes|\bok\b|\b1\b|t9ati|نعم|واخا|confirm/i.test(msg);
const reporter = /\bla\b|non|no|nbdel|report|\b2\b/i.test(msg);

// NOUVEAU : intention claire = au moins un des deux regex matche
// Si aucun ne matche → réponse illisible → on redemande
const intention_claire = confirme || reporter;

return [{ json: {
  confirme,
  reporter,
  intention_claire,   // ← nouveau flag pour router proprement
  telephone: tel,
  prenom:    sheetData.prenom    || ctx.prenom    || '',
  date_rdv:  sheetData.date_rdv  || ctx.date_rdv  || '',
  heure_rdv: sheetData.heure_rdv || ctx.heure_rdv || '',
  medecin:   sheetData.medecin   || ctx.medecin   || '',
  event_id:  sheetData.event_id  || ctx.event_id  || '',
  nb_annulations: parseInt(ctx.nb_annulations || '0') + 1
}}];

