={{ (() => {
  const attente = $('7-ACA-SHT2 — Chercher liste attente').first().json;
  const annul = $('7-ACA — Lire réponse confirmation annulation').first().json;
  const prenom = String(attente.prenom || '').trim();

  const date = String(annul.date_rdv || '');
  const heure = String(annul.heure_rdv || '');

  // Projection 7→2 (liste_attente saisie à la main, donc on projette ici)
  const projeterMode = (x) => {
    const m = String(x || '').trim().toLowerCase();
    if (m === 'francais_correct' || m === 'francais_approximatif') return 'francais_correct';
    if (m === 'arabe_fussha' || m === 'darija_latin' || m === 'darija_arabe' || m === 'mixte') return 'arabe_fussha';
    return 'francais_correct';
  };

  const mode = projeterMode(attente.mode_ecriture_final);

  // Nom médecin localisé selon le mode (config _AR / _FR)
  const cfg = $('00-CONFIG — Variables cabinet').first().json;
  const estArabe = (mode === 'arabe_fussha' || mode === 'darija_arabe');
  let medecin = estArabe
    ? String(cfg.PROD_NOM_MEDECIN_AR || cfg.PROD_NOM_MEDECIN || '').trim()
    : String(cfg.PROD_NOM_MEDECIN_FR || cfg.PROD_NOM_MEDECIN || '').trim();
  // ── Date localisée (FR ou AR fussha complet) ──
  const JOURS_AR = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
  const MOIS_AR  = ['يناير','فبراير','مارس','أبريل','ماي','يونيو','يوليوز','غشت','شتنبر','أكتوبر','نونبر','دجنبر'];
  const dateLisible = (dateStr, heureStr, m) => {
    const dS = String(dateStr || '').slice(0,10);
    const hS = String(heureStr || '');
    const arabe = (m === 'arabe_fussha' || m === 'darija_arabe');
    if (!dS) return arabe ? `${dS} على الساعة ${hS}` : `${dS} à ${hS.replace(':','h')}`;
    try {
      const d = new Date(`${dS}T${hS || '00:00'}:00`);
      if (arabe) return `${JOURS_AR[d.getDay()]} ${d.getDate()} ${MOIS_AR[d.getMonth()]} على الساعة ${hS}`;
      let aff = d.toLocaleDateString('fr-FR', {weekday:'long', day:'numeric', month:'long', year:'numeric'});
      aff = aff.charAt(0).toUpperCase() + aff.slice(1);
      return `${aff} à ${hS.replace(':','h')}`;
    } catch (e) { return arabe ? `${dS} على الساعة ${hS}` : `${dS} à ${hS.replace(':','h')}`; }
  };
  const affichage = dateLisible(date, heure, mode);

  // Préfixe "Dr" seulement si nom latin (les noms arabes portent déjà د.)
  let med = medecin;
  if (med && !estArabe && !/^dr\.?\s/i.test(med)) med = `Dr ${med}`;

  const hello = prenom ? `${prenom}` : '';

  if (mode === 'arabe_fussha') {
    return `مرحبا ${hello} 😊\nأصبح هناك موعد متاح مع ${med}:\n📅 ${affichage}\n\nهل تستطيعون الحضور؟\n✅ نعم\n❌ لا، شكرا`;
  }
  return `Bonjour ${hello} 😊\nUn créneau s'est libéré chez ${med} :\n📅 ${affichage}\n\nÊtes-vous disponible ?\n✅ Oui\n❌ Non, merci`;
})() }}

