parameters.jsCode:
const evenements = $input.all().map(e => e.json);
const rdv = $('REPORT — Chercher RDV existant').first().json;
const ownEventId = rdv.event_id;   /* RDV à reporter : à EXCLURE des conflits */

const horairesTravail = [
  '09:00','09:30','10:00','10:30','11:00','11:30',
  '14:00','14:30','15:00','15:30','16:00','16:30'
];
const joursOuvres = [1, 2, 3, 4, 5];      /* lun→ven (getUTCDay) */
const DUREE_CRENEAU_MIN = 30;
const TZ = 'Africa/Casablanca';
const maintenant = new Date();

/* ── AJOUT : récupération + projection du mode linguistique ──────────────
   Même cascade que 15-PRD (branche prise-RDV qui fonctionne).
   1re exécution report : le mode vient de SET — Profil linguistique final.
   Fallback : contexte session, puis parser, puis 'inconnu'. */
const safe = (fn, def) => { try { const v = fn(); return (v === undefined || v === null) ? def : v; } catch(e) { return def; } };

let ctxReport = {};
try { ctxReport = JSON.parse($('05 — Lire session patient').first().json.contexte || '{}'); } catch(e) { ctxReport = {}; }

const modeBrut =
  safe(() => $('SET — Profil linguistique final').first().json.mode_ecriture_final, '') ||
  ctxReport.mode_ecriture_final ||
  safe(() => $('09 — Parser réponse IA').first().json.mode_ecriture, '') ||
  'inconnu';

/* Projection vers les 2 modes de sortie (même règle que SET — Profil linguistique final) */
const m = String(modeBrut).trim().toLowerCase();
let mode_ecriture_final;
if (m === 'francais_correct' || m === 'francais_approximatif') mode_ecriture_final = 'francais_correct';
else if (m === 'arabe_fussha' || m === 'darija_latin' || m === 'darija_arabe' || m === 'mixte') mode_ecriture_final = 'arabe_fussha';
else mode_ecriture_final = 'francais_correct';
/* ─────────────────────────────────────────────────────────────────────── */

// ── Formatage de date patient localisé (voir Correctif A, même fonction) ──
const JOURS_AR = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
const MOIS_AR  = ['يناير','فبراير','مارس','أبريل','ماي','يونيو','يوليوز','غشت','شتنبر','أكتوبر','نونبر','دجنبر'];
function formaterDatePatient(instant, heure, mode) {
  const arabe = (mode === 'arabe_fussha' || mode === 'darija_arabe');
  if (arabe) {
    const ymd = instant.toLocaleDateString('en-CA', { timeZone: TZ });
    const [, M, D] = ymd.split('-').map(Number);
    const dow = new Date(`${ymd}T12:00:00+01:00`).getUTCDay();
    return `${JOURS_AR[dow]} ${D} ${MOIS_AR[M - 1]} على الساعة ${heure}`;
  }
  let aff = instant.toLocaleDateString('fr-FR', {
    timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
  });
  aff = aff.charAt(0).toUpperCase() + aff.slice(1);
  return `${aff} à ${heure.replace(':', 'h')}`;
}

/* ✅ Intervalles occupés en ms ABSOLUS, en sautant l'événement du patient lui-même */
const intervallesOccupes = evenements
  .filter(e => e.id !== ownEventId)
  .map(e => {
    const s = e.start ? (e.start.dateTime || e.start.date) : null;
    const f = e.end   ? (e.end.dateTime   || e.end.date)   : null;
    if (!s) return null;
    const startMs = new Date(s).getTime();
    const endMs = f ? new Date(f).getTime() : startMs + 30 * 60000;
    if (isNaN(startMs) || isNaN(endMs)) return null;
    return { startMs, endMs };
  })
  .filter(Boolean);

const creneauxLibres = [];

/* date locale Maroc "YYYY-MM-DD" pour aujourd'hui + k jours */
const ymdMaroc = (k) =>
  new Date(maintenant.getTime() + k * 86400000)
    .toLocaleDateString('en-CA', { timeZone: TZ });

for (let k = 0; k <= 14 && creneauxLibres.length < 3; k++) {
  const ymd = ymdMaroc(k);
  /* midi Maroc → getUTCDay() fiable pour le jour de semaine */
  const jourSemaine = new Date(`${ymd}T12:00:00+01:00`).getUTCDay();
  if (!joursOuvres.includes(jourSemaine)) continue;

  for (const heure of horairesTravail) {
    if (creneauxLibres.length >= 3) break;

    /* ✅ instant ABSOLU exact, offset Maroc explicite (indépendant du fuseau serveur) */
    const instant = new Date(`${ymd}T${heure}:00+01:00`);
    // CAS 3 — délai minimal de réservation : 30 min de tampon.
    // Un créneau à moins de 30 min est impraticable → on l'exclut.
    const DELAI_MIN_MS = 30 * 60 * 1000; // 30 minutes
    if (instant.getTime() <= maintenant.getTime() + DELAI_MIN_MS) continue;

    /* ✅ Ne pas reproposer le créneau ACTUEL du patient (il veut le quitter) */
    if (ymd === String(rdv.date_rdv).trim() && heure === String(rdv.heure_rdv).trim()) continue;

    const creneauStart = instant.getTime();
    const creneauEnd = creneauStart + DUREE_CRENEAU_MIN * 60000;

    /* ✅ chevauchement, pas égalité de début */
    const occupe = intervallesOccupes.some(ev =>
      creneauStart < ev.endMs && creneauEnd > ev.startMs
    );
    if (occupe) continue;

    const affichage = formaterDatePatient(instant, heure, mode_ecriture_final);
    creneauxLibres.push({
      index: String(creneauxLibres.length + 1),
      date_iso: ymd,
      heure,
      affichage
    });
  }
}

/* ✅ Formater le RDV actuel avec le MÊME format que les créneaux */
const instantActuel = new Date(`${String(rdv.date_rdv).trim()}T${String(rdv.heure_rdv).trim()}:00+01:00`);
const ancienneDateFormatee = formaterDatePatient(instantActuel, String(rdv.heure_rdv).trim(), mode_ecriture_final);


return [{ json: {
  telephone:              rdv.telephone,
  prenom:                 rdv.prenom,
  medecin:                rdv.medecin,
  ancien_event_id:        rdv.event_id,
  ancienne_date:          rdv.date_rdv,             // ISO brut conservé (utile en aval)
  ancienne_heure:         rdv.heure_rdv,            // ISO brut conservé
  ancienne_date_formatee: ancienneDateFormatee,     // champ formaté pour l'affichage
  mode_ecriture_final,                              // ← AJOUT : propagé vers contexte + nœuds report
  creneaux:               creneauxLibres
}}];

