  const prenom = String(v.prenom || '').trim();
  const creneau = v.creneau_choisi && v.creneau_choisi.affichage ? v.creneau_choisi.affichage : '';

  const projeter = (x) => {
    const m = String(x || '').trim().toLowerCase();
    if (m === 'arabe_fussha' || m === 'darija_arabe') return 'ar';
    return 'fr';
  };
  const isAr = projeter(v.mode_ecriture_final) === 'ar';

  let medecin = String((isAr ? cfg.PROD_NOM_MEDECIN_AR : cfg.PROD_NOM_MEDECIN_FR) || cfg.PROD_NOM_MEDECIN || '').trim();
  const contientArabe = /[\u0600-\u06FF]/.test(medecin);
  if (medecin && !contientArabe && !/^dr\.?\s/i.test(medecin)) medecin = `Dr ${medecin}`;

  if (isAr) {
    return (prenom ? `ممتاز ${prenom} 😊` : 'ممتاز 😊') +
           '\nتم تغيير موعدك :\n\n' + `📅 ${creneau}` +
           (medecin ? `\n🏥 ${medecin}` : '') +
           '\n\nنتمنى لك الصحة والعافية 🙏';
  }
  return (prenom ? `Parfait ${prenom} 😊` : 'Parfait 😊') +
         '\nVotre rendez-vous a bien été modifié :\n\n' + `📅 ${creneau}` +
         (medecin ? `\n🏥 ${medecin}` : '') +
         '\n\nNous vous souhaitons une bonne santé 🙏';
})() }}

