// Récupère le créneau libéré, stocké dans le contexte session par la branche annulation.
// ⚠️ FIX : les champs réels sont date_rdv / heure_rdv, à la RACINE du contexte
//          (pas dans un sous-objet creneau_libere).
let ctx = {};
try { ctx = JSON.parse($json.contexte || '{}'); } catch (e) { ctx = {}; }

const date  = ctx.date_rdv;     // ex: "2026-05-27"
const heure = ctx.heure_rdv;    // ex: "09:00"

// Garde-fou : si le contexte est incomplet, on échoue proprement plutôt
// que de fabriquer une date invalide silencieuse.
if (!date || !heure) {
  throw new Error('Contexte session incomplet : date_rdv ou heure_rdv manquant — ' + ($json.contexte || 'vide'));
}

// Calcul du end purement en string — plus lisible, pas de manip de Date
const [h, m] = heure.split(':').map(Number);
let endH = h, endM = m + 30;
if (endM >= 60) { endH += 1; endM -= 60; }
const pad = n => String(n).padStart(2, '0');

const start = `${date}T${heure}:00+01:00`;          // "2026-05-27T09:00:00+01:00"
const end   = `${date}T${pad(endH)}:${pad(endM)}:00+01:00`; // "2026-05-27T09:30:00+01:00"

return [{
  json: {
    ...$json,
    creneau: { date, heure, medecin: ctx.medecin || '' },
    event_id_libere: ctx.event_id || '',      // utile plus tard si besoin
    event_start: start,
    event_end: end,
    mode_ecriture_final: ctx.mode_ecriture_final || 'inconnu',
    prenom: ctx.prenom || ''
  }
}];

// Le nœud Calendar (Get Many) précède ce nœud.
// 0 événement trouvé = créneau encore libre. ≥1 = repris entre-temps.
// On compte les items RÉELS (avec un id Calendar) — un item vide "Always Output Data"
// ne doit pas être compté comme un événement.
const evenements = items.filter(i => i.json && i.json.id);
const libre = evenements.length === 0;

// On récupère les données préparées AVANT le Get Many
// (le Calendar a écrasé $json — il faut remonter au nœud Préparer événement).
const data = $('7-LA — Préparer événement').first().json;

return [{
  json: {
    ...data,
    creneau_libre: libre   // true = on peut réserver / false = trop tard
  }
}];

// Lecture déterministe Oui/Non — un simple oui/non ne mérite pas un appel GPT

// $json est la ligne SESSION. Le texte patient est dans le nœud 02 (message_brut).
const src = $('02 — Extraire données message').item.json;
const texte = String(src.message_brut || '').toLowerCase().trim();

// Variantes oui — étendues pour réduire les "inconnu"
const ouiVariants = [
  'oui', 'yes', 'yep', 'yup', 'ouais',
  'iyeh', 'iyyeh', 'eyeh', 'ah',
  'wah', 'waha', 'wakha', 'waxa',
  'ok', 'okay', 'd accord', 'daccord', 'dakor', 'parfait',
  'volontiers', 'avec plaisir',
  'نعم', 'اه', 'ايه', 'واخا', 'واها', 'موافق',
  '1', '✅', '👍'
];

// Variantes non — étendues
const nonVariants = [
  'non', 'no', 'nope',
  'la', 'lla', 'laa',
  'machi', 'masi', 'mashi',
  'pas possible', 'impossible', 'pas dispo', 'pas disponible',
  'لا', 'ماشي', 'مش',
  '2', '❌', '👎'
];

// On compare en mots entiers (pour éviter qu'un "ok" matche dans "okazion")
const mots = texte.split(/[^\p{L}\d✅❌👍👎]+/u).filter(Boolean);

let reponse = 'inconnu';
if (mots.some(m => ouiVariants.includes(m)))      reponse = 'oui';
else if (mots.some(m => nonVariants.includes(m))) reponse = 'non';

// Fallback : si pas de match exact, on retombe sur un includes() large
if (reponse === 'inconnu') {
  if (ouiVariants.some(v => texte.includes(v)))      reponse = 'oui';
  else if (nonVariants.some(v => texte.includes(v))) reponse = 'non';
}

return [{
  json: {
    ...$json,
    message_texte: texte,
    reponse_liste_attente: reponse,
    _debug_texte_lu: texte,
    _debug_mots: mots
  }
}];

