// ========================================================================
// 7-LA — Préparer notif suivant (branche refus / cascade)
// ========================================================================

// FIX angle mort LA : liste_attente est saisie à la main → mode non projeté
// à la lecture. On applique ici la MÊME projection 7→2 que
// « SET — Profil linguistique final » pour aligner l'offre + la session.
const projeterMode = (x) => {
  const m = String(x || '').trim().toLowerCase();
  if (m === 'francais_correct' || m === 'francais_approximatif') return 'francais_correct';
  if (m === 'arabe_fussha' || m === 'darija_latin' || m === 'darija_arabe' || m === 'mixte') return 'arabe_fussha';
  return 'francais_correct'; // inconnu / vide / inattendu → fallback FR
};

// Contexte du créneau libéré — lu depuis la session (comme 7-LA-WA Patient refuse)
let creneau = {};
try {
  creneau = JSON.parse($('7-LA — Lire réponse Oui/Non').item.json.contexte || '{}');
} catch (e) {
  creneau = {};
}

// Profil du suivant (P2) — remonté par 7-LA — Chercher suivant LA
const suivant = $('7-LA — Chercher suivant LA').first().json;

return [{
  json: {
    telephone: String(suivant.telephone),
    prenom: String(suivant.prenom || '').trim(),
    mode_ecriture_final: projeterMode(suivant.mode_ecriture_final), // ← FIX : projeté, plus brut
