={{ (() => {
  const d = $('7-LA — Préparer notif suivant').first().json;
  const prenom = String(d.prenom || '').trim();
  const mode = String(d.mode_ecriture_final || 'inconnu').trim().toLowerCase();

  // Nom médecin localisé selon le mode (config _AR / _FR, jamais la colonne Sheets)
  const cfg = $('00-CONFIG — Variables cabinet').first().json;
  const estArabe = (mode === 'arabe_fussha' || mode === 'darija_arabe');
  let medecin = estArabe
    ? String(cfg.PROD_NOM_MEDECIN_AR || cfg.PROD_NOM_MEDECIN || '').trim()
    : String(cfg.PROD_NOM_MEDECIN_FR || cfg.PROD_NOM_MEDECIN || '').trim();
  // Préfixe "Dr" seulement si nom latin (les noms arabes portent déjà د.)
  if (medecin && !estArabe && !/^dr\.?\s/i.test(medecin)) medecin = `Dr ${medecin}`;

  const date = String(d.date_rdv || '');
  const heure = String(d.heure_rdv || '').slice(0,5);

  // ── Date localisée ──
  const JOURS_AR = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
  const MOIS_AR  = ['يناير','فبراير','مارس','أبريل','ماي','يونيو','يوليوز','غشت','شتنبر','أكتوبر','نونبر','دجنبر'];
  const dateLisible = (dateStr, heureStr, m) => {
    const dS = String(dateStr || '').slice(0,10);
    const hS = String(heureStr || '');
    const arabe = (m === 'arabe_fussha' || m === 'darija_arabe');
    if (!dS) return arabe ? `${dS} على الساعة ${hS}` : `${dS} à ${hS.replace(':','h')}`;
    try {
      const dd = new Date(`${dS}T${hS || '00:00'}:00`);
      if (arabe) return `${JOURS_AR[dd.getDay()]} ${dd.getDate()} ${MOIS_AR[dd.getMonth()]} على الساعة ${hS}`;
      let aff = dd.toLocaleDateString('fr-FR', {weekday:'long', day:'numeric', month:'long', year:'numeric'});
      aff = aff.charAt(0).toUpperCase() + aff.slice(1);
      return `${aff} à ${hS.replace(':','h')}`;
    } catch (e) { return arabe ? `${dS} على الساعة ${hS}` : `${dS} à ${hS.replace(':','h')}`; }
  };
  const affichage = dateLisible(date, heure, mode);
  const hello = prenom || '';

  if (mode === 'darija_latin') return `Mrhba ${hello} 😊\nChi bla9a tlaq 3nd ${medecin} :\n📅 ${affichage}\n\nWach t9der tji ?\n✅ Iyeh\n❌ La, chokran`;
  if (mode === 'darija_arabe') return `مرحبا ${hello} 😊\nشي بلاصة تلقات عند ${medecin}:\n📅 ${affichage}\n\nواش تقدر تجي؟\n✅ إيه\n❌ لا، شكرا`;
  if (mode === 'arabe_fussha') return `مرحبا ${hello} 😊\nأصبح هناك موعد متاح مع ${medecin}:\n📅 ${affichage}\n\nهل تستطيعون الحضور؟\n✅ نعم\n❌ لا، شكرا`;
  if (mode === 'francais_correct') return `Bonjour ${hello} 😊\nUn créneau s'est libéré chez ${medecin} :\n📅 ${affichage}\n\nÊtes-vous disponible ?\n✅ Oui\n❌ Non, merci`;
  if (mode === 'francais_approximatif') return `Bonjour ${hello} 😊\nUn créneau libre chez ${medecin} :\n📅 ${affichage}\n\nVous êtes dispo ?\n✅ Oui\n❌ Non merci`;
  if (mode === 'mixte') return `Mrhba ${hello} 😊\nUn créneau s'est libéré chez ${medecin} :\n📅 ${affichage}\n\nWach disponible ?\n✅ Oui\n❌ Non, chokran`;
  return `Bonjour ${hello} 😊\nUn créneau s'est libéré chez ${medecin} :\n📅 ${affichage}\n\nÊtes-vous disponible ?\n✅ Oui\n❌ Non, merci`;
})() }}

