// Lit les données de la réponse de confirmation d'annulation
const data = $('7-ACA — Lire réponse confirmation annulation').first().json;

const date = String(data.date_rdv || '').trim();
const heure = String(data.heure_rdv || '').trim();

let annulation_tardive = false;
let rdv_expire = false; // NOUVEAU : RDV déjà passé (no-show non traité à temps)

try {
  const d = new Date(`${date}T${heure}:00`);
  const diffMs = d - new Date();
  annulation_tardive = diffMs < 2 * 60 * 60 * 1000;
  rdv_expire = diffMs < 0; // heure du RDV dépassée => créneau inutilisable
} catch (e) {
  annulation_tardive = false;
  rdv_expire = false;
}

return [{
  json: {
    ...data,
    annulation_tardive,
    rdv_expire,
    type_annulation: annulation_tardive ? 'tardive' : 'normale'
  }
}];

