={{ (() => {
  const annul = $('7-ACA — Lire réponse confirmation annulation').first().json;

// Helper format date unifié
  const fmtDate = (iso) => {
    if (!iso) return 'Non renseignée';
    try {
      const x = new Date(String(iso).slice(0,10) + 'T00:00:00');
      let j = x.toLocaleDateString('fr-FR', { weekday: 'long' });
      j = j.charAt(0).toUpperCase() + j.slice(1);
      const jj = String(x.getDate()).padStart(2,'0');
      const mm = String(x.getMonth()+1).padStart(2,'0');
      return `${j} ${jj}/${mm}/${x.getFullYear()}`;
    } catch(e) { return String(iso); }
  };

  const attente = (() => {
    try {
      return $('7-ACA-SHT2 — Chercher liste attente').first().json || {};
    } catch (e) {
      return {};
    }
  })();

  const flag = (() => {
    try {
      return $('7-ACA-FLAG — Classer annulation').first().json || {};
    } catch (e) {
      return {};
    }
  })();

  const prenom = String(annul.prenom || 'Non renseigné').trim();
  const telephone = String(annul.telephone || '').replace(/\D/g, '');
  const medecin = String(annul.medecin || 'Non renseigné').trim();
  const date = String(annul.date_rdv || '').trim();
  const heure = String(annul.heure_rdv || '').trim();

  if (flag.rdv_expire === true) {
    return (
      `🔴 Annulation d'un RDV déjà passé (no-show)\n\n` +
      `👤 Patient : ${prenom}\n` +
      `📞 Téléphone : ${telephone}\n` +
      `📅 Créneau : ${fmtDate(date)} à ${heure}\n` +
      `🏥 Médecin : ${medecin}\n\n` +
      `⏹️ Créneau expiré — non proposé à la liste d'attente.`
    );
  }

  const telAttente = String(attente.telephone || '').replace(/\D/g, '');
  const prenomAttente = String(attente.prenom || '').trim();
  const dispoAttente = String(attente.disponibilites || '').trim();

  const hasAttente = telAttente !== '';

  let annulationTardive = false;

  if (typeof flag.annulation_tardive === 'boolean') {
    annulationTardive = flag.annulation_tardive;
  } else {
    try {
      const d = new Date(`${date}T${heure}:00`);
      annulationTardive = (d - new Date()) < 2 * 60 * 60 * 1000;
    } catch (e) {
      annulationTardive = false;
    }
  }

  const titre = annulationTardive
    ? '🔴 ANNULATION DERNIÈRE MINUTE'
    : '🔴 Annulation RDV';

  const situationAttente = hasAttente
    ? (
      '✅ Un patient en liste d’attente a été notifié.\n' +
      `👤 Patient en attente : ${prenomAttente || 'Non renseigné'}\n` +
      `📞 Téléphone attente : ${telAttente}\n` +
      `🕒 Disponibilités indiquées : ${dispoAttente || 'Non renseignées'}\n\n` +
      '⏳ Le système attend maintenant sa réponse Oui/Non.'
    )
    : (
      '🟠 Aucun patient en liste d’attente.\n' +
      'Le créneau reste libre dans l’agenda.'
    );

  return (
    `${titre}\n\n` +
    `👤 Patient annulé : ${prenom}\n` +
    `📞 Téléphone : ${telephone}\n` +
    `📅 Créneau libéré : ${fmtDate(date)} à ${heure}\n` +
    `🏥 Médecin : ${medecin}\n\n` +
    situationAttente
  );
})() }}

