// ── READS en tête (un seul IIFE root, try/catch) ──────────────────
// Contexte stringifié écrit à l'exécution précédente (état inscription_LA)
let ctx = {};
try {
  const raw = $json.contexte || $('05 — Lire session patient').first().json.contexte || '{}';
  ctx = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
} catch (e) {
  ctx = {};
}

// Texte patient : dans ce workflow il est dans le nœud 02, champ message_brut
const texteBrut = String(
  $('02 — Extraire données message').first().json.message_brut || ''
).trim();

// ── LOGIQUE ────────────────────────────────────────────────────────
// Normalisation : minuscules, sans accents, pour matcher oui/non multilingue
const t = texteBrut.toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// Détection OUI (fr + darija latin + arabe)
const estOui = /\b(oui|o|wah|wa|iyeh|naam|na3am|ah)\b/.test(t)
  || /نعم|أجل|واخا|واه|ايه/.test(texteBrut);

// Détection NON (fr + darija latin + arabe)
const estNon = /\b(non|no|n|la|lla|makayn)\b/.test(t)
  || /لا|لأ|ماشي/.test(texteBrut);

// Décision : OUI prioritaire ; sinon NON ; sinon = non reconnu (traité comme NON par sécurité)
const reponse = estOui ? 'OUI' : (estNon ? 'NON' : 'NON');

return [{
  json: {
    telephone: String($json.telephone || ctx.telephone || ''),
    prenom: ctx.prenom || '',
    medecin_souhaite: ctx.medecin_souhaite || '',
    mode_ecriture_final: ctx.mode_ecriture_final || 'inconnu',
    reponse
  }
}];

