let mode_ecriture_final = 'inconnu';
try {
  const ctx = JSON.parse($('05 — Lire session patient').first().json.contexte || '{}');
  mode_ecriture_final = ctx.mode_ecriture_final || 'inconnu';
} catch (e) { /* contexte vide ou malformé → fallback inconnu */ }

let intention = 'autre';

// 1 (latin/arabe) ou mots-clés report → report
if (['1', '١', 'reporter', 'report', 'changer', 'modifier'].includes(msg)) {
  intention = 'report';
}
// 2 (latin/arabe) ou mots-clés annulation → annulation
if (['2', '٢', 'annuler', 'annulation', 'cancel'].includes(msg)) {
  intention = 'annulation';
}
// tout autre choix → intention reste 'autre'
// → fallback 'extra' de 10 → menu principal (comportement MVP acceptable)

return [{
  json: {
    telephone: tel,
    intention,
    mode_ecriture_final  // propagé vers les nœuds REPORT/ANNUL en aval
  }
}];
